#include <iostream>
#include <map>
#include <sstream>
#include <string>
using namespace std;

class RedisDB {
    map<string, string> data;
public:
    string handle(const string& cmd) {
        istringstream iss(cmd);
        string op; iss >> op;
        if (op == "SET") {
            string key, val; iss >> key >> val;
            data[key] = val;
            return "OK";
        } else if (op == "GET") {
            string key; iss >> key;
            auto it = data.find(key);
            return it != data.end() ? it->second : "(nil)";
        } else if (op == "DEL") {
            string key; iss >> key;
            return to_string(data.erase(key));
        } else if (op == "KEYS") {
            string result;
            for (auto& [k, v] : data) result += k + " ";
            return result.empty() ? "(empty)" : result;
        }
        return "ERR unknown command";
    }
};

int main() {
    RedisDB db;
    cout << db.handle("SET name Alice") << endl;
    cout << db.handle("GET name") << endl;
    cout << db.handle("SET age 30") << endl;
    cout << db.handle("KEYS") << endl;
    cout << db.handle("DEL name") << endl;
    cout << db.handle("KEYS") << endl;
    return 0;
}
